kind":"design","source":"design","note":"head_d 5.5 + clearance"},"cbore_depth":{"value":3.2,"kind":"design","source":"design","note":"head sits flush so the disc lies flat on the lid"},"disc_hole_d":{"value":3.3,"kind":"world","source":"measured","note":"disc mounting hole diameter"},"disc_hole_pitch":{"value":33.5,"kind":"world","source":"measured","note":"30.2 measured between hole inner edges + 3.3 hole diameter = centre pitch; holes at 3 and 9 o'clock"},"disc_pcb_t":{"value":1.6,"kind":"world","source":"guessed","note":"disc PCB thickness, could not be measured; standard 1.6. Controls the M3x6 screw engagement (4.4 mm into a 4 mm insert)"},"disc_dia":{"value":241.5,"kind":"world","source":"measured","note":"derived from hole-to-edge readings (102.54 and 102.24 outside of hole to edge) plus the hole spacing; the person could not measure the diameter directly. Not used in the box geometry"},"wire_slot_w":{"value":18,"kind":"design","source":"guessed","note":"slot in the lid for the 4 wires at 12 o'clock; the disc connector position could not be measured, so it is generous"},"wire_slot_y0":{"value":6,"kind":"design","source":"guessed"},"wire_slot_y1":{"value":42,"kind":"design","source":"guessed"},"pb_w":{"value":50,"kind":"world","source":"measured","note":"perfboard width (x)"},"pb_l":{"value":70,"kind":"world","source":"measured","note":"perfboard length (y)"},"pb_hole_d":{"value":2.4,"kind":"world","source":"measured"},"pb_hole_edge":{"value":0.9,"kind":"world","source":"measured","note":"edge of hole to board edge"},"pb_t":{"value":1.6,"kind":"world","source":"guessed","note":"perfboard thickness could not be measured"},"pb_cy":{"value":-11,"kind":"design","source":"design","note":"perfboard centre y: its bottom edge sits 1 mm from the bottom wall"},"esp_height":{"value":16,"kind":"world","source":"measured","note":"ESP32 top above perfboard top"},"esp_port_bottom":{"value":12.54,"kind":"world","source":"measured","note":"bottom of USB-C receptacle above perfboard top"},"esp_port_h":{"value":3.2,"kind":"world","source":"measured"},"esp_port_w":{"value":10.67,"kind":"world","source":"measured"},"esp_port_offset":{"value":3.99,"kind":"world","source":"measured","note":"port centre off the ESP32 centreline"},"esp_end_gap":{"value":7.53,"kind":"world","source":"measured","note":"ESP32 USB end to perfboard edge; read as the ESP32 end sitting 7.53 inside the perfboard edge (ambiguous)"},"usb_w":{"value":44,"kind":"design","source":"design","note":"wide opening in the bottom wall because the port's sideways position on the perfboard is uncertain (about 5 to 13 mm off centre, side unknown)"},"usb_h":{"value":12,"kind":"design","source":"guessed","note":"plug housing height was not measurable; typical USB-C overmold is 6-9 mm tall, 12-16 wide"},"wscrew_head_d":{"value":9,"kind":"world","source":"asked","note":"#8 round-head wall screws, heads at most 9 mm"},"wscrew_shank_d":{"value":4.2,"kind":"world","source":"guessed","note":"#8 thread outer diameter, standard"},"wscrew_head_t":{"value":4.5,"kind":"world","source":"guessed","note":"typical #8 round head height; pocket is 5"},"key_x":{"value":30,"kind":"design","source":"design","note":"keyholes at x = +-30, 60 mm apart"},"key_y":{"value":25,"kind":"design","source":"design","note":"entry circle centre; the narrow slot runs up from here"},"key_len":{"value":12,"kind":"design","source":"design"}}, "parts": [{"id":"box","role":"final","material":"matte white PLA","print_orientation":"back face (the wall side) flat on the bed, open side up","use_orientation":"back face against the wall, open side facing out","code":"def build(p):
    W=p.box_w; H=p.box_h; D=p.depth; bt=p.back_t; w=p.wall
    def cyl(x,y,z0,h,d):
        return cq.Workplane('XY').workplane(offset=z0).center(x,y).circle(d/2).extrude(h)
    def blk(x,y,z0,sx,sy,h):
        return cq.Workplane('XY').workplane(offset=z0).center(x,y).rect(sx,sy).extrude(h)
    outer = cq.Workplane('XY').box(W,H,D,centered=(True,True,False)).edges('|Z').fillet(p.corner_r)
    cav = cq.Workplane('XY').workplane(offset=bt).rect(W-2*w,H-2*w).extrude(D).edges('|Z').fillet(p.corner_r-w)
    body = outer.cut(cav)
    # lid posts with insert holes
    for sx in (-1,1):
        for sy in (-1,1):
            body = body.union(cyl(sx*p.post_xy, sy*p.post_xy, bt-0.5, D-bt+0.5, p.post_d))
    for sx in (-1,1):
        for sy in (-1,1):
            body = body.cut(cyl(sx*p.post_xy, sy*p.post_xy, D-p.post_hole_depth, p.post_hole_depth+1, p.insert_hole_d))
    # perfboard standoffs
    hx = p.pb_w/2 - p.pb_hole_edge - p.pb_hole_d/2
    hy = p.pb_l/2 - p.pb_hole_edge - p.pb_hole_d/2
    for sx in (-1,1):
        for sy in (-1,1):
            x=sx*hx; y=p.pb_cy+sy*hy
            body = body.union(cyl(x,y,bt-0.5,p.standoff_h+0.5,p.standoff_d))
    for sx in (-1,1):
        for sy in (-1,1):
            x=sx*hx; y=p.pb_cy+sy*hy
            body = body.cut(cyl(x,y,bt+p.standoff_h-p.m2_pilot_depth,p.m2_pilot_depth+1,p.m2_pilot_d))
    # keyholes: entry circle + narrow slot in the rear layer, wide pocket behind it
    entry = p.wscrew_head_d+0.8
    slot = p.wscrew_shank_d+0.6
    L = p.key_len
    for sx in (-1,1):
        x0=sx*p.key_x; y0=p.key_y
        body = body.cut(cyl(x0,y0,-1,p.rear_t+1,entry))
        body = body.cut(blk(x0,y0+L/2,-1,slot,L,p.rear_t+1))
        pk = cyl(x0,y0,p.rear_t,p.pocket_d,entry).union(cyl(x0,y0+L,p.rear_t,p.pocket_d,entry)).union(blk(x0,y0+L/2,p.rear_t,entry,L,p.pocket_d))
        body = body.cut(pk)
    # USB-C opening in the bottom wall
    port_z = bt+p.standoff_h+p.pb_t+p.esp_port_bottom+p.esp_port_h/2
    op = cq.Workplane('XY').box(p.usb_w, w+2, p.usb_h).translate((0, -H/2+w/2, port_z))
    body = body.cut(op)
    return body
"},{"id":"lid","role":"final","material":"matte white PLA","print_orientation":"underside flat on the bed, front face up","use_orientation":"on the rim of the box, front face out; the LED disc screws to its front","code":"def build(p):
    W=p.box_w; H=p.box_h; T=p.lid_t
    def cyl(x,y,z0,h,d):
        return cq.Workplane('XY').workplane(offset=z0).center(x,y).circle(d/2).extrude(h)
    lid = cq.Workplane('XY').box(W,H,T,centered=(True,True,False)).edges('|Z').fillet(p.corner_r)
    for sx in (-1,1):
        for sy in (-1,1):
            x=sx*p.post_xy; y=sy*p.post_xy
            lid = lid.cut(cyl(x,y,-1,T+2,p.m3_clear_d))
            lid = lid.cut(cyl(x,y,T-p.cbore_depth,p.cbore_depth+1,p.cbore_d))
    for sx in (-1,1):
        lid = lid.cut(cyl(sx*p.disc_hole_pitch/2,0,T-p.disc_insert_depth,p.disc_insert_depth+1,p.insert_hole_d))
    ys=(p.wire_slot_y0+p.wire_slot_y1)/2
    sl = cq.Workplane('XY').workplane(offset=-1).center(0,ys).rect(p.wire_slot_w,p.wire_slot_y1-p.wire_slot_y0).extrude(T+2)
    lid = lid.cut(sl)
    return lid
